def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'),
                      ensure_ascii=False, allow_nan=False).encode('utf-8')

def exact_json(raw, *, canonical_required=True):
    def pairs(items):
        result = {}
        for key, value in items:
            require(key not in result, 'STARTUP_DUPLICATE_JSON_KEY')
            result[key] = value
        return result
    result = json.loads(raw, object_pairs_hook=pairs,
        parse_constant=lambda value: (_ for _ in ()).throw(StartupRefusal('STARTUP_NONFINITE_JSON')))
    if canonical_required:
        require(raw in (canonical(result), canonical(result) + b'\n'), 'STARTUP_NONCANONICAL_JSON')
    return result

def record(value):
    kind=type(value)
    if kind in _KNOWN.values():
        return {'type':kind.__name__,'fields':{field.name:record(getattr(value,field.name)) for field in fields(value)}}
    if kind is bytes:return {'type':'bytes','value':value.hex()}
    if kind is float:
        import struct
        return {'type':'float','bits':struct.pack('!d',value).hex()}
    if kind is int:
        magnitude=abs(value)
        return {'type':'integer','negative':value<0,
            'magnitude':magnitude.to_bytes((magnitude.bit_length()+7)//8,'little').hex()}
    if kind in (str,bool) or value is None:return {'type':kind.__name__,'value':value}
    if kind in (tuple,list):return {'type':kind.__name__,'items':[record(item) for item in value]}
    if kind is dict:
        if any(type(key) is not str for key in value):raise ValueError('scoped record keys must be exact strings')
        return {'type':'dict','fields':{key:record(item) for key,item in value.items()}}
    raise ValueError('complete declared scoped source record required')

def archive(value):
    """Explicit DTO tags retain bytes, tuple/list shape and every record field."""
    def lift(item):
        kind = type(item)
        if kind in _RECORDS:
            return ['record', kind.__module__, kind.__name__,
                    [[field.name, lift(getattr(item, field.name))] for field in fields(kind)]]
        if kind is WorldState:
            return ['world-state', item.value]
        if kind is dict:
            if any(type(key) not in (str, bytes) for key in item):
                raise WorldlineError('RECOVERY_PACKET_KEY', 'a full capture key has no original grammar')
            return ['object', [[lift(key), lift(val)] for key, val in item.items()]]
        if kind is tuple:
            return ['tuple', [lift(val) for val in item]]
        if kind is list:
            return ['list', [lift(val) for val in item]]
        if kind is int:
            magnitude=abs(item)
            return ['integer-magnitude',item<0,magnitude.to_bytes((magnitude.bit_length()+7)//8,'little')]
        if item is None or kind in (bytes, bool, float, str):
            return ['atom', item]
        raise WorldlineError('RECOVERY_PACKET_TYPE', 'a full capture value has no original DTO grammar',
                            {'type': kind.__name__})
    return encode(lift(value))

def encode(value):
    """Lossless full-value encoding; neither JSON projection nor digest shortening."""
    def lift(item):
        if type(item) is bytes:
            return ['bytes', base64.b64encode(item).decode('ascii')]
        if isinstance(item, list):
            return ['list', [lift(x) for x in item]]
        if isinstance(item, tuple):
            return ['tuple', [lift(x) for x in item]]
        if isinstance(item, dict):
            if any(not isinstance(key, str) for key in item):
                _refuse('FINALIZATION_OBJECT_KEY_INVALID')
            return ['object', [[key, lift(val)] for key, val in item.items()]]
        if item is None or type(item) in (bool, int, float) or isinstance(item, str):
            return ['scalar', item]
        _refuse('FINALIZATION_VALUE_UNSUPPORTED')
    return value_bytes(lift(value))

def value_bytes(value) -> bytes:
    def encode(item):
        if item is None: return ['null']
        if type(item) is bool: return ['bool', item]
        if isinstance(item, str): return ['str', _b64(identity(item))]
        if type(item) is int:
            value = abs(item)
            return ['int', item < 0, _b64(value.to_bytes((value.bit_length() + 7) // 8, 'little'))]
        if type(item) is float: return ['float', _b64(struct.pack('!d', item))]
        if isinstance(item, (list, tuple)): return ['array', [encode(x) for x in item]]
        if isinstance(item, dict):
            if any(not isinstance(key, str) for key in item):
                raise TerminalRefused('CAPTURE_OBJECT_KEY_INVALID')
            return ['object', [[_b64(identity(key)), encode(val)] for key, val in item.items()]]
        raise TerminalRefused('CAPTURE_VALUE_UNSUPPORTED')
    return canonical(encode(value))
